import { test, expect } from '@playwright/test';

test.describe('Notification Dismissal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should dismiss notification by clicking close button', async ({ page }) => {
    // Verify notification is visible
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Verify notification contains close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click close button to dismiss notification
    await closeButton.click();

    // Verify notification is no longer visible
    await expect(notification).not.toBeVisible();

    // Verify notification count is decremented
    const notificationCount = page.getByText(/notifications/i);
    await expect(notificationCount).toContainText('0');

    // Verify success message appears
    const successMessage = page.getByText(/notification dismissed/i);
    await expect(successMessage).toBeVisible();
  });

  test('should not dismiss notification when clicking outside close button', async ({ page }) => {
    // Verify notification is visible
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Verify notification contains close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click outside close button to dismiss notification
    const outsideElement = page.locator('[data-testid="outside-element"]');
    await outsideElement.click();

    // Verify notification is still visible
    await expect(notification).toBeVisible();

    // Verify notification count remains unchanged
    const notificationCount = page.getByText(/notifications/i);
    await expect(notificationCount).toContainText('1');

    // Verify success message does not appear
    const successMessage = page.getByText(/notification dismissed/i);
    await expect(successMessage).not.toBeVisible();
  });
});
